// SPDX-License-Identifier: Apache-2.0
// Host test of ftmPwm/FtmPwmGroup.h (IO-61) with a register model of the FlexTimer. The configuration is generated by
// tools/bswgen from an own test profile; test_ftm_pwm_group.py renders the variants (alignment edge/center, trigger
// none/zero_low/zero_high) and passes what the PROJECT asks for as macros, so the checks below compare the simulated
// waveform with the project values, never with the generated constants:
//   EXPECT_CLOCK_HZ, EXPECT_FREQUENCY_HZ, EXPECT_DEADTIME_NS, EXPECT_CENTER (0/1),
//   EXPECT_TRIGGER (0 none, 1 zero_low, 2 zero_high)
//
// Register model (S32K1xx RM, FTM chapter; the facts the board still has to confirm are marked "board"):
// - counter clocked every 2^PS input clocks; edge: 0 .. MOD, then CNTIN again; center (CPWMS): 0 .. MOD .. 0
// - combine pair (edge): channel 2k output high for C(2k)V <= CNT < C(2k+1)V; center: high while CNT < C(2k)V
// - COMP: channel 2k+1 is the complement; DTEN: every rising edge of both outputs is delayed by DTVAL x DTPS input
//   clocks; OUTMASK forces the channel inactive
// - C(n)V of a pair with SYNCEN is a buffer, loaded into the comparator when the counter reaches MOD (SYNC.CNTMAX) and
//   a software trigger (SYNC.SWSYNC) is pending, which clears SWSYNC; without SYNCEN the value takes effect at once
// - EXTTRIG.INITTRIGEN: trigger when the counter takes CNTIN (edge: restart after MOD; center: counter minimum,
//   board); CHjTRIG: trigger when the counter takes C(j)V
// Printed values (MEASURED ...) are read by test_ftm_pwm_group.py to compare edge and center.

#include "ftmPwm/FtmPwmGroup.h"

#include <cstdio>
#include <cstdlib>
#include <vector>

FTM_Type fakeFtm = {};

#ifndef EXPECT_CENTER
#error "EXPECT_* come from test_ftm_pwm_group.py"
#endif

namespace
{
using namespace bios::ftmPwm;

unsigned checks   = 0U;
unsigned failures = 0U;

#define CHECK(c)                                                     \
    do                                                               \
    {                                                                \
        ++checks;                                                    \
        if (!(c))                                                    \
        {                                                            \
            ++failures;                                              \
            std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); \
        }                                                            \
    } while (0)

constexpr uint8_t MAX_PAIRS = 4U;

struct Sample
{
    bool hs[MAX_PAIRS];
    bool ls[MAX_PAIRS];
    bool trigger;
    bool load;
};

class Model
{
public:
    explicit Model(FTM_Type& f) : _f(f) {}

    void start()
    {
        _cnt      = _f.CNTIN;
        _up       = true;
        _prescale = 0U;
        for (uint8_t ch = 0U; ch < 8U; ++ch)
        {
            _active[ch] = _f.CONTROLS[ch].CnV; // counter stopped until now: written values are effective
            _run[ch]    = 0U;
        }
        _newValue = true;
    }

    Sample step()
    {
        Sample s{};
        bool const center = (_f.SC & FTM_SC_CPWMS_MASK) != 0U;
        uint32_t const mod = _f.MOD & 0xFFFFU;
        for (uint8_t ch = 0U; ch < 8U; ++ch)
        {
            if (!syncEnabled(ch))
            {
                _active[ch] = _f.CONTROLS[ch].CnV;
            }
        }
        if (_newValue)
        {
            if ((_cnt == mod) && ((_f.SYNC & FTM_SYNC_CNTMAX_MASK) != 0U) && ((_f.SYNC & FTM_SYNC_SWSYNC_MASK) != 0U))
            {
                for (uint8_t ch = 0U; ch < 8U; ++ch)
                {
                    if (syncEnabled(ch))
                    {
                        _active[ch] = _f.CONTROLS[ch].CnV;
                    }
                }
                _f.SYNC = _f.SYNC & ~FTM_SYNC_SWSYNC_MASK;
                s.load  = true;
            }
            if ((_cnt == mod) && !s.load)
            {
                s.load = true; // loading point without pending values (marks the period all the same)
            }
            if (((_f.EXTTRIG & FTM_EXTTRIG_INITTRIGEN_MASK) != 0U) && (_cnt == (_f.CNTIN & 0xFFFFU)))
            {
                s.trigger = true;
            }
            for (uint8_t ch = 0U; ch < 8U; ++ch)
            {
                if (((_f.EXTTRIG & channelTriggerMask(ch)) != 0U) && (_cnt == _active[ch]))
                {
                    s.trigger = true;
                }
            }
        }
        for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
        {
            uint8_t const ch = PAIRS[i].highChannel;
            bool raw;
            if (center)
            {
                raw = _cnt < _active[ch];
            }
            else
            {
                raw = (_active[ch] <= _cnt) && (_cnt < _active[ch + 1U]);
            }
            s.hs[i] = output(ch, raw);
            s.ls[i] = output(static_cast<uint8_t>(ch + 1U), !raw);
        }
        // advance one input clock
        _newValue = false;
        if (++_prescale >= (1U << (_f.SC & FTM_SC_PS_MASK)))
        {
            _prescale = 0U;
            _newValue = true;
            if (center)
            {
                if (_up)
                {
                    if (_cnt >= mod)
                    {
                        _up = false;
                        --_cnt;
                    }
                    else
                    {
                        ++_cnt;
                    }
                }
                else
                {
                    if (_cnt <= (_f.CNTIN & 0xFFFFU))
                    {
                        _up = true;
                        ++_cnt;
                    }
                    else
                    {
                        --_cnt;
                    }
                }
            }
            else
            {
                _cnt = (_cnt >= mod) ? (_f.CNTIN & 0xFFFFU) : (_cnt + 1U);
            }
        }
        return s;
    }

private:
    bool syncEnabled(uint8_t ch) const
    {
        return (_f.COMBINE & (FTM_COMBINE_SYNCEN0_MASK << (8U * (ch / 2U)))) != 0U;
    }

    static uint32_t channelTriggerMask(uint8_t ch)
    {
        static uint32_t const masks[8] = {FTM_EXTTRIG_CH0TRIG_MASK, FTM_EXTTRIG_CH1TRIG_MASK, FTM_EXTTRIG_CH2TRIG_MASK,
                                          FTM_EXTTRIG_CH3TRIG_MASK, FTM_EXTTRIG_CH4TRIG_MASK, FTM_EXTTRIG_CH5TRIG_MASK,
                                          FTM_EXTTRIG_CH6TRIG_MASK, FTM_EXTTRIG_CH7TRIG_MASK};
        return masks[ch];
    }

    bool output(uint8_t ch, bool raw)
    {
        static uint32_t const dividers[4] = {1U, 1U, 4U, 16U};
        uint8_t const pair       = static_cast<uint8_t>(ch / 2U);
        uint32_t const reg       = pairDeadtime(pair);
        uint32_t const dead      = (reg & FTM_PAIR0DEADTIME_DTVAL_MASK)
                              * dividers[(reg & FTM_PAIR0DEADTIME_DTPS_MASK) >> FTM_PAIR0DEADTIME_DTPS_SHIFT];
        bool const dten          = (_f.COMBINE & (FTM_COMBINE_DTEN0_MASK << (8U * pair))) != 0U;
        _run[ch]                 = raw ? (_run[ch] + 1U) : 0U;
        bool const out           = raw && (!dten || (_run[ch] > dead));
        bool const masked        = ((_f.OUTMASK >> ch) & 1U) != 0U;
        return out && !masked;
    }

    uint32_t pairDeadtime(uint8_t pair) const
    {
        switch (pair)
        {
            case 0U: return _f.PAIR0DEADTIME;
            case 1U: return _f.PAIR1DEADTIME;
            case 2U: return _f.PAIR2DEADTIME;
            default: return _f.PAIR3DEADTIME;
        }
    }

    FTM_Type& _f;
    uint32_t _cnt      = 0U;
    bool _up           = true;
    uint32_t _prescale = 0U;
    bool _newValue     = true;
    uint32_t _active[8] = {};
    uint32_t _run[8]    = {};
};

std::vector<Sample> trace;
std::vector<size_t> loads;

void run(Model& m, size_t clocks)
{
    for (size_t i = 0U; i < clocks; ++i)
    {
        Sample const s = m.step();
        if (s.load)
        {
            loads.push_back(trace.size());
        }
        trace.push_back(s);
    }
}

bool allHs(size_t t, bool on)
{
    for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
    {
        if (trace[t].hs[i] != on)
        {
            return false;
        }
    }
    return true;
}

// Run [a, b) of samples around t in which every high side is `on`; returns the doubled midpoint a + b - 1.
long runMid2(size_t t, bool on)
{
    if (!allHs(t, on))
    {
        return -1;
    }
    size_t a = t;
    size_t b = t;
    while ((a > 0U) && allHs(a - 1U, on))
    {
        --a;
    }
    while ((b + 1U < trace.size()) && allHs(b + 1U, on))
    {
        ++b;
    }
    return static_cast<long>(a + b);
}

long absl(long v) { return (v < 0) ? -v : v; }

constexpr uint32_t PS_CLOCKS = 1U << PRESCALER_SHIFT;

struct PeriodFacts
{
    size_t from;
    size_t to; // [from, to): one period between two loading points
};

// Duty of pair i in the period [p.from, p.to): on time of the high side plus its dead time, over the period.
void checkPeriod(PeriodFacts const& p, uint16_t const* q15, char const* what)
{
    size_t const len = p.to - p.from;
    uint32_t const deadClocks
        = DEADTIME_TICKS * DEADTIME_PRESCALER; // generated value, checked against the project in main()
    for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
    {
        size_t on = 0U;
        size_t lsOn = 0U;
        size_t both = 0U;
        for (size_t t = p.from; t < p.to; ++t)
        {
            on += trace[t].hs[i] ? 1U : 0U;
            lsOn += trace[t].ls[i] ? 1U : 0U;
            both += (trace[t].hs[i] && trace[t].ls[i]) ? 1U : 0U;
        }
        CHECK(both == 0U); // never both switches of a half bridge on
        if ((q15[i] == 0U) || (q15[i] >= Q15_ONE))
        {
            CHECK(on == ((q15[i] == 0U) ? 0U : len));
            continue;
        }
        // on time + dead time = duty x period, within the counter resolution (center: 2 ticks per step)
        long const expected2 = static_cast<long>((static_cast<uint64_t>(q15[i]) * len * 2U) / Q15_ONE);
        long const got2      = static_cast<long>(2U * (on + deadClocks));
        long const tol2      = static_cast<long>(2U * 2U * PS_CLOCKS);
        if (absl(got2 - expected2) > tol2)
        {
            std::printf("  %s pair %u: on %zu + dead %u of %zu, expected %.1f\n", what, i, on, deadClocks, len,
                        expected2 / 2.0);
        }
        CHECK(absl(got2 - expected2) <= tol2);
        // two dead times per period: both switches off
        CHECK(len - on - lsOn == 2U * deadClocks);
    }
}

// IO-45: FtmPwmGroup::highSideOnTicks() against the simulated waveform of the period [p.from, p.to): 0 for a high side
// that never turns on, the whole period for one that never turns off, otherwise the high-side samples plus the dead
// time that delays the rising edge - exactly, in input clocks.
void checkReadBack(PeriodFacts const& p, char const* what)
{
    FtmPwmGroup const group(fakeFtm);
    size_t const len          = p.to - p.from;
    uint32_t const deadClocks = DEADTIME_TICKS * DEADTIME_PRESCALER;
    for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
    {
        size_t on = 0U;
        for (size_t t = p.from; t < p.to; ++t)
        {
            on += trace[t].hs[i] ? 1U : 0U;
        }
        uint32_t ticks = 0xFFFFFFFFU;
        CHECK(group.highSideOnTicks(i, ticks));
        uint64_t const expected
            = (on == 0U) ? 0U : ((on == len) ? static_cast<uint64_t>(PERIOD_TICKS) * PS_CLOCKS : (on + deadClocks));
        if (static_cast<uint64_t>(ticks) * PS_CLOCKS != expected)
        {
            std::printf("  %s pair %u: read back %u ticks, waveform %zu clocks (+ dead %u) of %zu\n", what, i, ticks,
                        on, deadClocks, len);
        }
        CHECK(static_cast<uint64_t>(ticks) * PS_CLOCKS == expected);
        CHECK(ticks <= PERIOD_TICKS);
    }
}

// IO-45: masked, forced and inverted pairs, set by hand on the registers and restored afterwards.
void checkReadBackOfForcedStates(FtmPwmGroup const& group)
{
    uint32_t const outmask = fakeFtm.OUTMASK;
    uint32_t const swoctrl = fakeFtm.SWOCTRL;
    uint32_t const invctrl = fakeFtm.INVCTRL;
    uint8_t const hs       = PAIRS[0].highChannel;
    uint32_t const pair0   = 3U << hs;
    uint32_t ticks         = 0U;
    // a pair with a duty, then masked: off; the other pairs keep their values
    fakeFtm.CONTROLS[hs].CnV      = pairValues(16384U).c0;
    fakeFtm.CONTROLS[hs + 1U].CnV = pairValues(16384U).c1;
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks > 0U) && (ticks < PERIOD_TICKS));
    // one tick away from the end stops still switches
#ifdef NX_FTM_PWM_CENTER
    fakeFtm.CONTROLS[hs].CnV = COUNTER_TOP; // high except at the turning point
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == PERIOD_TICKS - 1U));
    fakeFtm.CONTROLS[hs].CnV = COUNTER_TOP + 1U;
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == PERIOD_TICKS));
    fakeFtm.CONTROLS[hs].CnV = 1U; // high at the counter minimum only
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == 1U));
#else
    fakeFtm.CONTROLS[hs].CnV      = 0U;
    fakeFtm.CONTROLS[hs + 1U].CnV = PERIOD_TICKS - 1U;
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == PERIOD_TICKS - 1U));
    fakeFtm.CONTROLS[hs].CnV      = 7U;
    fakeFtm.CONTROLS[hs + 1U].CnV = 8U;
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == 1U));
    fakeFtm.CONTROLS[hs + 1U].CnV = 0xFFFFU; // beyond the period: until its end
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == PERIOD_TICKS - 7U));
#endif
    fakeFtm.CONTROLS[hs].CnV      = pairValues(16384U).c0;
    fakeFtm.CONTROLS[hs + 1U].CnV = pairValues(16384U).c1;
    fakeFtm.OUTMASK = outmask | pair0;
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == 0U));
    fakeFtm.OUTMASK = outmask | (1U << hs); // only the high side masked: no state of a half bridge
    CHECK(!group.highSideOnTicks(0U, ticks));
    fakeFtm.OUTMASK = outmask & ~pair0;
    // the safe state and the debug halt guard: every channel of the group forced inactive (SWOCTRL = CHANNEL_MASK)
    fakeFtm.SWOCTRL = CHANNEL_MASK;
    for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
    {
        CHECK(group.highSideOnTicks(i, ticks) && (ticks == 0U));
    }
    fakeFtm.SWOCTRL = 1U << hs; // only the high side forced: no state of a half bridge
    CHECK(!group.highSideOnTicks(0U, ticks));
    fakeFtm.SWOCTRL = pair0 | (1U << (8U + hs)); // high side forced to 1, low side to 0: on for the whole period
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == PERIOD_TICKS));
    fakeFtm.OUTMASK = outmask | pair0; // ... unless the output mask takes both away
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == 0U));
    fakeFtm.OUTMASK = outmask & ~pair0;
    fakeFtm.SWOCTRL = pair0 | (3U << (8U + hs)); // both forced to 1: a shoot-through pattern, no state
    CHECK(!group.highSideOnTicks(0U, ticks));
    fakeFtm.SWOCTRL = 0U;
    fakeFtm.INVCTRL = 1U << (hs / 2U); // inverted pair: the channel values mean the other switch
    CHECK(!group.highSideOnTicks(0U, ticks));
    fakeFtm.OUTMASK = outmask;
    fakeFtm.SWOCTRL = swoctrl;
    fakeFtm.INVCTRL = invctrl;
}

} // namespace

int main()
{
    // --- generated register values against the project (EXPECT_*) --------------------------------------------
    CHECK(PAIR_COUNT <= MAX_PAIRS);
    CHECK(CLOCK_HZ == EXPECT_CLOCK_HZ);
    CHECK(CENTER_ALIGNED == (EXPECT_CENTER != 0));
    CHECK(((CONFIGURATION.sc & FTM_SC_CPWMS_MASK) != 0U) == (EXPECT_CENTER != 0));
    for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
    {
        uint32_t const bits = CONFIGURATION.combine >> (8U * (PAIRS[i].highChannel / 2U));
        CHECK(((bits & FTM_COMBINE_COMBINE0_MASK) != 0U) == (EXPECT_CENTER == 0)); // combine only for edge
        CHECK((bits & (FTM_COMBINE_COMP0_MASK | FTM_COMBINE_DTEN0_MASK | FTM_COMBINE_SYNCEN0_MASK))
              == (FTM_COMBINE_COMP0_MASK | FTM_COMBINE_DTEN0_MASK | FTM_COMBINE_SYNCEN0_MASK));
    }
#if EXPECT_TRIGGER == 0
    CHECK(CONFIGURATION.exttrig == 0U);
#else
    CHECK(CONFIGURATION.exttrig != 0U);
#endif
    // conversions of the RTE target pwm.<pair> (0.01 %) and the Q15 values
    static_assert(centiPercentToQ15(0U) == 0U && centiPercentToQ15(10000U) == Q15_ONE, "0.01 % -> Q15 ends");
    static_assert(centiPercentToQ15(5000U) == 16384U && centiPercentToQ15(1U) == 3U, "0.01 % -> Q15 rounding");
    static_assert(edgeValues(4000U, 0U).c0 == 2000U && edgeValues(4000U, 0U).c1 == 2000U, "edge 0 %");
    static_assert(edgeValues(4000U, Q15_ONE).c0 == 0U && edgeValues(4000U, Q15_ONE).c1 == 4000U, "edge 100 %");
    static_assert(edgeValues(4000U, 16384U).c0 == 1000U && edgeValues(4000U, 16384U).c1 == 3000U, "edge 50 %");
    static_assert(edgeValues(4000U, 65535U).c1 == 4000U, "edge above 100 % saturates");
    static_assert(centerValues(1600U, 0U).c0 == 0U, "center 0 %");
    static_assert(centerValues(1600U, 16384U).c0 == 800U, "center 50 %");
    static_assert(centerValues(1600U, Q15_ONE).c0 == 1601U && centerValues(1600U, 40000U).c0 == 1601U,
                  "center 100 % and above: CnV above the turning point");

    // --- init as the driver does it: FTM configured, channels set up, counter started, pairs unmasked ----------
    bios::tFtm ftm(fakeFtm);
    ftm.stop();
    ftm.init(&CONFIGURATION);
    FtmPwmGroup group(fakeFtm);
    group.setupChannels();
    ftm.start();
#ifdef NX_FTM_PWM_TRIGGER_CHANNEL
    CHECK(((fakeFtm.OUTMASK >> TRIGGER_CHANNEL) & 1U) != 0U); // trigger channel never drives a pin
    CHECK(fakeFtm.CONTROLS[TRIGGER_CHANNEL].CnV == TRIGGER_VALUE);
#endif
    fakeFtm.OUTMASK = fakeFtm.OUTMASK & ~CHANNEL_MASK;
    Model model(fakeFtm);
    model.start();

    uint16_t const dutiesA[MAX_PAIRS] = {18022U, 21299U, 24576U, 27853U}; // 55 %, 65 %, 75 %, 85 %
    uint16_t const dutiesB[MAX_PAIRS] = {9830U, 13107U, 16384U, 19661U};  // 30 %, 40 %, 50 %, 60 %
    CHECK(group.writeDutiesQ15(dutiesA, PAIR_COUNT));
    CHECK(!group.writeDutiesQ15(dutiesA, static_cast<uint8_t>(PAIR_COUNT + 1U))); // wrong count: nothing written
    CHECK(!group.writeDutiesQ15(nullptr, PAIR_COUNT));

    size_t const periodGuess = static_cast<size_t>(EXPECT_CLOCK_HZ / EXPECT_FREQUENCY_HZ);
    run(model, 4U * periodGuess);
    CHECK(loads.size() >= 3U);
    if (loads.size() < 3U)
    {
        std::printf("no loading points\n");
        return 1;
    }
    // --- period, frequency, dead time against the project --------------------------------------------------------
    PeriodFacts const p{loads[1], loads[2]};
    size_t const len = p.to - p.from;
    uint64_t const f = static_cast<uint64_t>(EXPECT_FREQUENCY_HZ) * len;
    CHECK(100U * ((f > EXPECT_CLOCK_HZ) ? (f - EXPECT_CLOCK_HZ) : (EXPECT_CLOCK_HZ - f)) <= EXPECT_CLOCK_HZ);
    uint32_t const deadClocks = DEADTIME_TICKS * DEADTIME_PRESCALER;
    CHECK(static_cast<uint64_t>(deadClocks) * 1000000000ULL >= static_cast<uint64_t>(EXPECT_DEADTIME_NS) * EXPECT_CLOCK_HZ);
    CHECK(static_cast<uint64_t>(deadClocks - DEADTIME_PRESCALER) * 1000000000ULL
          < static_cast<uint64_t>(EXPECT_DEADTIME_NS) * EXPECT_CLOCK_HZ);
    // measured dead time: the gap from a high side off to its low side on
    size_t gap = 0U;
    for (size_t t = p.from + 1U; t < p.to; ++t)
    {
        if (trace[t - 1U].hs[0] && !trace[t].hs[0])
        {
            size_t g = 0U;
            while ((t + g < trace.size()) && !trace[t + g].ls[0] && !trace[t + g].hs[0])
            {
                ++g;
            }
            gap = g;
            break;
        }
    }
    CHECK(gap == deadClocks);
    std::printf("MEASURED period_clocks=%zu deadtime_clocks=%zu tick_clocks=%u\n", len, gap, PS_CLOCKS);
    checkPeriod(p, dutiesA, "A");

    // --- pulse position: all high-side pulses concentric, loading point in the middle of zero_low ---------------
    long const midLow2  = runMid2(loads[2], false);
    size_t const middle = p.from + (len / 2U);
    long const midHigh2 = runMid2(middle, true);
    CHECK(midLow2 >= 0);
    CHECK(midHigh2 >= 0);
    long const tolerance2 = static_cast<long>(deadClocks + 2U * PS_CLOCKS + 2U); // dead time shifts by half
    CHECK(absl(midLow2 - 2L * static_cast<long>(loads[2])) <= tolerance2);
    CHECK(absl((midLow2 - midHigh2) - static_cast<long>(len)) <= static_cast<long>(2U * PS_CLOCKS + 2U));
    for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
    {
        size_t a = middle;
        while (trace[a - 1U].hs[i])
        {
            --a;
        }
        size_t b = middle;
        while (trace[b + 1U].hs[i])
        {
            ++b;
        }
        CHECK(absl(static_cast<long>(a + b) - midHigh2) <= static_cast<long>(2U * PS_CLOCKS + 1U));
    }

    // --- trigger: one per period, at the instant of the project -------------------------------------------------
    std::vector<size_t> triggers;
    for (size_t t = p.from; t < p.to; ++t)
    {
        if (trace[t].trigger)
        {
            triggers.push_back(t);
        }
    }
#if EXPECT_TRIGGER == 0
    CHECK(triggers.empty());
#else
    CHECK(triggers.size() == 1U);
    if (triggers.size() == 1U)
    {
        long const t2 = 2L * static_cast<long>(triggers[0]);
        // the trigger instant against the middle of the zero vector measured from the waveform
        long const target2 = (EXPECT_TRIGGER == 1) ? midLow2 : midHigh2;
        long offset2       = t2 - target2;
        if (EXPECT_TRIGGER == 1)
        {
            // zero_low measured in the period after the loading point: same distance one period later
            long const next2 = t2 + 2L * static_cast<long>(len);
            offset2          = (absl(next2 - target2) < absl(offset2)) ? (next2 - target2) : offset2;
        }
        std::printf("MEASURED trigger_offset_clocks=%.1f (trigger minus middle of the zero vector)\n", offset2 / 2.0);
        CHECK(absl(offset2) <= tolerance2);
    }
#endif

    // --- one synchronisation step: all pairs change at the same loading point ------------------------------------
    size_t const before = trace.size();
    run(model, len - (trace.size() - loads.back()) - 3U * PS_CLOCKS); // shortly before the next loading point
    CHECK(trace.size() > before);
    CHECK(group.writeDutiesQ15(dutiesB, PAIR_COUNT));
    CHECK(!group.writeDutiesQ15(dutiesB, PAIR_COUNT)); // still pending: a second write in the same period is flagged
    size_t const loadsBefore = loads.size();
    run(model, 3U * len);
    CHECK(loads.size() >= loadsBefore + 2U);
    if (loads.size() >= loadsBefore + 2U)
    {
        checkPeriod(PeriodFacts{loads[loadsBefore - 1U], loads[loadsBefore]}, dutiesA, "old");
        checkPeriod(PeriodFacts{loads[loadsBefore], loads[loadsBefore + 1U]}, dutiesB, "new");
        // IO-45: the on time read back from the registers is the one of the waveform - high-side samples of the
        // period plus the dead time that delays its rising edge, in input clocks
        checkReadBack(PeriodFacts{loads[loadsBefore], loads[loadsBefore + 1U]}, "new");
    }

    // --- one pair, the ends 0 % and 100 % -------------------------------------------------------------------------
    uint16_t ends[MAX_PAIRS] = {0U, 65535U, 0U, Q15_ONE};
    CHECK(group.writeDutiesQ15(ends, PAIR_COUNT));
    size_t const loadsEnds = loads.size();
    run(model, 4U * len);
    CHECK(loads.size() >= loadsEnds + 3U);
    if (loads.size() >= loadsEnds + 3U)
    {
        // the second period: in the first one the 100 % high side still waits its dead time after the change
        checkPeriod(PeriodFacts{loads[loadsEnds + 1U], loads[loadsEnds + 2U]}, ends, "ends");
        checkReadBack(PeriodFacts{loads[loadsEnds + 1U], loads[loadsEnds + 2U]}, "ends");
    }
    // IO-45: the end stops exactly - 0 and a full period, whatever the counting
    uint32_t ticks = 1234U;
    CHECK(group.highSideOnTicks(0U, ticks) && (ticks == 0U));
    CHECK(group.highSideOnTicks(1U, ticks) && (ticks == PERIOD_TICKS));
    CHECK(!group.highSideOnTicks(PAIR_COUNT, ticks));
    checkReadBackOfForcedStates(group);
    CHECK(group.writePairQ15(0U, 16384U));
    CHECK(!group.writePairQ15(PAIR_COUNT, 16384U));

    std::printf("FtmPwmGroupHostTest (center %d, trigger %d, %u pairs): %u checks, %u failures\n", EXPECT_CENTER,
                EXPECT_TRIGGER, PAIR_COUNT, checks, failures);
    return (failures == 0U) ? 0 : 1;
}
